1	// Package indexroom implements chain ingestion with optional block
2	// timestamps, reorg handling, consistent paginated transaction queries, and
3	// time-bucketed transaction statistics over the main chain.
4	package indexroom
5	
6	import (
7		"fmt"
8		"sync"
9		"unicode/utf8"
10	)
11	
12	// Block is one ingested block with its transactions.
13	//
14	// Time is the optional block timestamp as non-negative Unix seconds. A nil
15	// pointer means the block carries no timestamp and is distinct from a
16	// timestamp of zero. Append and Reorg reject negative values; stored blocks
17	// keep their own copy, so mutating the pointer or its target after a call
18	// never affects the index. Block timestamps need not be monotonic: equal
19	// values and values that decrease with height are both accepted.
20	type Block struct {
21		Height int64
22		// Hash, Parent, and every Txs identifier must be valid UTF-8; Append and
23		// Reorg reject a block carrying invalid bytes rather than letting a
24		// snapshot export silently rewrite them to U+FFFD. Txs keeps empty and
25		// duplicated identifiers, order, case, and surrounding whitespace
26		// exactly as given.
27		Hash   string
28		Parent string
29		Txs    []string
30		Time   *int64
31	}
32	
33	// Index is the durable chain view.
34	//
35	// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
36	// concurrent use; the exported fields are meant for read-only inspection
37	// after all calls have finished.
38	type Index struct {
39		Blocks map[int64]Block
40		ByHash map[string]int64
41		Tip    int64
42	
43		mu  sync.Mutex
44		key [32]byte
45	}
46	
47	// New returns an empty index.
48	func New() *Index {
49		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
50	}
51	
52	// reorgAppliedHookLocked is a test-only rendezvous invoked from Reorg once
53	// the alternate branch has fully replaced the old tip range, while index.mu
54	// is still held and before the call returns. It is nil in production; reorg
55	// regression tests park a successful reorg here with the new chain already in
56	// effect, so a QueryTimeStats issued at that instant is forced to wait and,
57	// once it runs, must observe the complete new chain.
58	var reorgAppliedHookLocked func(newTip int64)
59	
60	// appendStoredHookLocked is a test-only rendezvous invoked from appendLocked
61	// right after an Append has fully recorded its accepted block — the block is
62	// in Blocks and ByHash and Tip has advanced — while index.mu is still held
63	// and before the call returns. It fires for the Append path only, never for
64	// stores performed inside Reorg. It is nil in production; Append/Reorg
65	// interleaving tests park a successful append here so the block is committed
66	// but the call has not returned, forcing a concurrent Reorg to acquire the
67	// lock against exactly that intermediate state instead of relying on
68	// scheduling luck.
69	var appendStoredHookLocked func(height int64)
70	
71	// Append accepts a block only when it extends the current tip, keeping the
72	// chain linear. Re-submitting a block identical to one already on the main
73	// chain is a successful no-op. A block whose hash, parent, or any transaction
74	// identifier carries invalid UTF-8 is rejected with an error naming the
75	// height and field (and the zero-based tx position); a rejected append leaves
76	// the index untouched.
77	func (index *Index) Append(block Block) error {
78		index.mu.Lock()
79		defer index.mu.Unlock()
80		return index.appendLocked(block)
81	}
82	
83	func (index *Index) appendLocked(block Block) error {
84		if err := validateBlockEncoding(block); err != nil {
85			return err
86		}
87		if block.Hash == "" {
88			return errInvalid("block needs a hash")
89		}
90		if block.Time != nil && *block.Time < 0 {
91			return errInvalid("block time must not be negative")
92		}
93		if index.Tip == 0 {
94			// Empty index: only the first block at height 1 is accepted; its
95			// parent becomes the chain start identifier and need not be indexed.
96			if block.Height != 1 {
97				return errInvalid("first block must be at height 1")
98			}
99			index.storeLocked(block)
100			if appendStoredHookLocked != nil {
101				appendStoredHookLocked(block.Height)
102			}
103			return nil
104		}
105		if old, exists := index.Blocks[block.Height]; exists {
106			if sameBlock(old, block) {
107				return nil
108			}
109			return errInvalid("height already indexed with different content")
110		}
111		if block.Height != index.Tip+1 {
112			return errInvalid("block height must extend the current tip")
113		}
114		if block.Parent != index.Blocks[index.Tip].Hash {
115			return errInvalid("parent does not match the current tip")
116		}
117		if _, exists := index.ByHash[block.Hash]; exists {
118			return errInvalid("hash already indexed at another height")
119		}
120		index.storeLocked(block)
121		if appendStoredHookLocked != nil {
122			appendStoredHookLocked(block.Height)
123		}
124		return nil
125	}
126	
127	// Reorg replaces the tip range with an alternate branch and reports the
128	// dropped old heights in ascending order. The branch is validated in full
129	// before anything is applied — including UTF-8 validity of every block's
130	// hash, parent, and transaction identifiers, even in the last block — so a
131	// rejected reorg leaves the index exactly as it was and reports no dropped
132	// heights. Heights whose old block is identical to the new one are not
133	// reported; re-submitting the branch already in effect returns an empty list.
134	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
135		index.mu.Lock()
136		defer index.mu.Unlock()
137	
138		if len(blocks) == 0 {
139			return nil, errInvalid("empty branch")
140		}
141		// Every identifier must be valid UTF-8 before any lookup or mutation.
142		// The first block's parent need not be indexed, but it still has to be
143		// encodable, and an error in the last block must reject the whole branch.
144		for _, block := range blocks {
145			if err := validateBlockEncoding(block); err != nil {
146				return nil, err
147			}
148		}
149		ancestor, ok := index.ByHash[blocks[0].Parent]
150		if !ok {
151			return nil, errInvalid("branch parent is unknown")
152		}
153		if blocks[0].Height != ancestor+1 {
154			return nil, errInvalid("branch must start at the ancestor height plus one")
155		}
156		seen := make(map[string]bool, len(blocks))
157		for i, block := range blocks {
158			if block.Hash == "" {
159				return nil, errInvalid("block needs a hash")
160			}
161			if block.Time != nil && *block.Time < 0 {
162				return nil, errInvalid("block time must not be negative")
163			}
164			if seen[block.Hash] {
165				return nil, errInvalid("duplicate hash inside branch")
166			}
167			seen[block.Hash] = true
168			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
169				return nil, errInvalid("hash conflicts with a retained block")
170			}
171			if i > 0 {
172				prev := blocks[i-1]
173				if block.Height != prev.Height+1 {
174					return nil, errInvalid("branch heights must be consecutive")
175				}
176				if block.Parent != prev.Hash {
177					return nil, errInvalid("branch parent does not match the previous block")
178				}
179			}
180		}
181	
182		// Everything validated; compute the dropped heights before mutating.
183		newTip := blocks[len(blocks)-1].Height
184		dropped := []int64{}
185		for height := ancestor + 1; height <= index.Tip; height++ {
186			if height > newTip {
187				dropped = append(dropped, height)
188				continue
189			}
190			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
191				dropped = append(dropped, height)
192			}
193		}
194		for height := ancestor + 1; height <= index.Tip; height++ {
195			delete(index.ByHash, index.Blocks[height].Hash)
196			delete(index.Blocks, height)
197		}
198		index.Tip = ancestor
199		for _, block := range blocks {
200			index.storeLocked(block)
201		}
202		if reorgAppliedHookLocked != nil {
203			reorgAppliedHookLocked(index.Tip)
204		}
205		return dropped, nil
206	}
207	
208	// storeLocked records a validated block, copying its transactions and
209	// timestamp so later caller-side mutation cannot alter the stored block.
210	func (index *Index) storeLocked(block Block) {
211		if block.Txs != nil {
212			txs := make([]string, len(block.Txs))
213			copy(txs, block.Txs)
214			block.Txs = txs
215		}
216		if block.Time != nil {
217			t := *block.Time
218			block.Time = &t
219		}
220		index.Blocks[block.Height] = block
221		index.ByHash[block.Hash] = block.Height
222		index.Tip = block.Height
223	}
224	
225	// validateBlockEncoding rejects a block whose hash, parent, or any
226	// transaction identifier contains invalid UTF-8 bytes. JSON snapshots can
227	// only carry valid UTF-8 — the encoder would silently rewrite bad bytes to
228	// U+FFFD, merging distinct identifiers after a restore — so such a block can
229	// never enter the index. The error names the block height and the field; a
230	// bad transaction identifier also names its zero-based position. A genuine
231	// U+FFFD is valid UTF-8 and is never rejected by this check.
232	func validateBlockEncoding(block Block) error {
233		if !utf8.ValidString(block.Hash) {
234			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "hash"))
235		}
236		if !utf8.ValidString(block.Parent) {
237			return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "parent"))
238		}
239		for position, tx := range block.Txs {
240			if !utf8.ValidString(tx) {
241				return errInvalid(fmt.Sprintf("block at height %d: field %q element %d contains invalid UTF-8 bytes", block.Height, "txs", position))
242			}
243		}
244		return nil
245	}
246	
247	// sameBlock reports whether two blocks are identical: same height, hash,
248	// parent, transactions in order, and timestamp presence and value. An empty
249	// tx list equals a missing one, but a missing timestamp never equals zero.
250	func sameBlock(a, b Block) bool {
251		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
252			return false
253		}
254		if len(a.Txs) != len(b.Txs) {
255			return false
256		}
257		for i := range a.Txs {
258			if a.Txs[i] != b.Txs[i] {
259				return false
260			}
261		}
262		if (a.Time == nil) != (b.Time == nil) {
263			return false
264		}
265		return a.Time == nil || *a.Time == *b.Time
266	}
267	
268	type errInvalid string
269	
270	func (e errInvalid) Error() string { return string(e) }
271

