91	// The swap itself: both reused hashes land at heights different from their
92	// old ones, the branch replaces everything above the retained ancestor, and
93	// the dropped report lists every changed old height exactly once.
94	func TestReorgRelocatedHashesSwapHeights(t *testing.T) {
95		index := buildRelocatedHashOldChain(t)
96	
97		dropped, err := index.Reorg(relocatedHashBranch())
98		if err != nil {
99			t.Fatalf("relocated-hash reorg refused: %v", err)
100		}
101		// h4 and h5 are still indexed after the reorg, but the blocks AT heights
102		// 4 and 5 changed, so both heights must be reported; the retained range
103		// (1..2) must not appear.
104		if want := []int64{3, 4, 5}; !reflect.DeepEqual(dropped, want) {
105			t.Fatalf("dropped=%v, want %v (a hash reappearing must not hide a changed height)", dropped, want)
106		}
107		if index.Tip != 5 {
108			t.Fatalf("tip=%d, want 5", index.Tip)
109		}
