233				page.TotalMatches, page.MatchedBlocks, page.ToHeight, len(wantHits))
234		}
235	}
236	
237	// The reuse budget is exactly the replaced suffix. A branch that takes a
238	// hash from the retained range (the ancestor or below), or that uses one
239	// hash twice, is rejected in full — no dropped heights, and the chain, the
240	// old blocks, and the query results stay exactly as they were, even when
241	// the conflict sits in the branch's last block.
